package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	searchTerm := r.URL.Query().Get("q")

	// Build base query
	var queryParts []string
	queryParts = append(queryParts, "SELECT id, name, price, category, description FROM products WHERE 1=1")

	// Category filter - uses parameterized approach
	var args []interface{}
	argIdx := 1

	if category != "" {
		queryParts = append(queryParts, fmt.Sprintf(" AND category = $%d", argIdx))
		args = append(args, category)
		argIdx++
	}

	// Price range filters - parameterized
	if minPrice != "" {
		queryParts = append(queryParts, fmt.Sprintf(" AND price >= $%d", argIdx))
		args = append(args, minPrice)
		argIdx++
	}
	if maxPrice != "" {
		queryParts = append(queryParts, fmt.Sprintf(" AND price <= $%d", argIdx))
		args = append(args, maxPrice)
		argIdx++
	}

	// Full-text search - VULNERABLE: direct string interpolation
	if searchTerm != "" {
		// Developer note: using to_tsquery for performance, building dynamic query
		// The search term is split and joined for multi-word support
		terms := strings.Fields(searchTerm)
		tsQuery := strings.Join(terms, " & ")
		queryParts = append(queryParts, fmt.Sprintf(" AND to_tsvector('english', name || ' ' || description) @@ to_tsquery('english', '%s')", tsQuery))
	}

	// Sort - ALSO VULNERABLE but less obvious
	if sortField != "" {
		queryParts = append(queryParts, fmt.Sprintf(" ORDER BY %s", sortField))
	} else {
		queryParts = append(queryParts, " ORDER BY id ASC")
	}

	queryParts = append(queryParts, " LIMIT 50")

	finalQuery := strings.Join(queryParts, "")
	log.Printf("Executing query: %s", finalQuery)

	rows, err := db.Query(finalQuery, args...)
	if err != nil {
		http.Error(w, "Search failed", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, cat, desc string
		var price float64
		rows.Scan(&id, &name, &price, &cat, &desc)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"category":"%s"}`, id, name, price, cat)))
		first = false
	}
	w.Write([]byte("\n]"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
